select f.id, f.file_room, j.room_no db_room, f.file_cust, j.customer_name db_cust,
       f.order_date, j.order_date db_date, j.working_status
from f join jobs j on j.id=f.id
where upper(regexp_replace(f.file_room,'[^A-Za-z0-9]','','g')) <> upper(regexp_replace(coalesce(j.room_no,''),'[^A-Za-z0-9]','','g'))
   or btrim(f.file_cust) <> btrim(coalesce(j.customer_name,''))
   or j.order_date is not null;